"""Secure executor for structured actions generated by FORGEX agents.

Filesystem actions are confined to the active workspace. Terminal actions are
never executed through a shell: they require an injected TerminalExecutor,
which performs authorization, approval, supervision, and auditing.
"""

from __future__ import annotations

import difflib
import fnmatch
import inspect
import logging
import shlex
from collections.abc import Awaitable, Callable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from forgex.tools.terminal.executor import TerminalExecutor
from forgex.tools.terminal.models import (
    TerminalExecutionStatus,
    TerminalRequest,
)

logger = logging.getLogger(__name__)


class ActionExecutionError(RuntimeError):
    """Raised when an agent action execution fails."""


@dataclass(slots=True)
class ActionExecutionResult:
    """Outcome of executing a single agent action."""

    action_type: str
    target: str
    success: bool
    diff: str = ""
    output: str = ""
    error: str | None = None
    metadata: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "type": self.action_type,
            "target": self.target,
            "success": self.success,
            "diff": self.diff,
            "output": self.output,
            "error": self.error,
            "metadata": self.metadata,
        }


class ActionExecutor:
    """Execute agent actions with workspace and terminal security boundaries."""

    _PROTECTED_PATTERNS = (
        ".git",
        ".git/*",
        ".env",
        ".env.*",
        "*.pem",
        "*.key",
        "id_rsa",
        "id_ed25519",
        "*.p12",
        "*.pfx",
    )

    def __init__(
        self,
        workspace: Path | None = None,
        *,
        terminal_executor: TerminalExecutor | None = None,
        file_approval_handler: Callable[[str, str], bool | Awaitable[bool]] | None = None,
    ) -> None:
        self.workspace = Path(workspace).expanduser().resolve() if workspace else None
        self.terminal_executor = terminal_executor
        self.file_approval_handler = file_approval_handler

    def _resolve_target(self, workspace: Path, target_str: str) -> Path:
        clean_target = target_str.strip().replace("\\", "/")
        if not clean_target or "\x00" in clean_target:
            raise ActionExecutionError("A valid relative target path is required.")
        candidate = Path(clean_target)
        if candidate.is_absolute() or (candidate.drive and candidate.drive != workspace.drive):
            raise ActionExecutionError("Absolute paths are not permitted.")
        target_path = (workspace / candidate).resolve()
        try:
            target_path.relative_to(workspace.resolve())
        except ValueError as exc:
            raise ActionExecutionError(
                f"Security error: target path '{target_str}' escapes workspace."
            ) from exc

        relative = target_path.relative_to(workspace.resolve()).as_posix()
        if any(
            fnmatch.fnmatchcase(relative, pattern)
            or any(fnmatch.fnmatchcase(part, pattern) for part in relative.split("/"))
            for pattern in self._PROTECTED_PATTERNS
        ):
            raise ActionExecutionError(f"Protected path cannot be modified: {relative}")
        return target_path

    async def execute_action(
        self,
        workspace: Path,
        action: dict[str, Any],
    ) -> ActionExecutionResult:
        raw_type = str(action.get("type") or action.get("action") or "note").lower().strip()
        target = str(action.get("target") or action.get("file") or action.get("path") or "").strip()
        content = action.get("content") if "content" in action else action.get("text")

        if raw_type in {"create", "write", "add"}:
            return await self._execute_write(workspace, target, content, overwrite=False)
        if raw_type in {"modify", "edit", "update", "patch"}:
            return await self._execute_write(workspace, target, content, overwrite=True)
        if raw_type in {"delete", "remove"}:
            return await self._execute_delete(workspace, target)
        if raw_type in {"command", "exec", "terminal", "run"}:
            command = target or str(action.get("command") or "").strip()
            return await self._execute_command(workspace, command)

        if raw_type in {"note", "explain", "analysis", "documentation"}:
            return ActionExecutionResult(
                action_type=raw_type,
                target=target,
                success=True,
                output=str(action.get("details") or content or "Informational action."),
            )

        return ActionExecutionResult(
            action_type=raw_type,
            target=target,
            success=False,
            error=f"Unsupported action type: {raw_type}",
        )

    async def _execute_write(
        self,
        workspace: Path,
        target_str: str,
        content: Any,
        *,
        overwrite: bool,
    ) -> ActionExecutionResult:
        if not target_str:
            return ActionExecutionResult("write", "", False, error="No target file specified.")
        try:
            target = self._resolve_target(workspace, target_str)
            if not await self._request_file_approval(
                "modify" if overwrite else "create", target_str
            ):
                raise ActionExecutionError("File change was not approved by the operator.")
            target_existed = target.exists()
            if target_existed and not target.is_file():
                raise ActionExecutionError("Write target exists and is not a regular file.")
            if target_existed and not overwrite:
                raise ActionExecutionError("Target already exists; use an explicit modify action.")

            target.parent.mkdir(parents=True, exist_ok=True)
            text_content = str(content) if content is not None else ""
            old_text = (
                target.read_text(encoding="utf-8", errors="replace") if target.exists() else ""
            )
            diff = "\n".join(
                difflib.unified_diff(
                    old_text.splitlines(),
                    text_content.splitlines(),
                    fromfile=f"a/{target_str}",
                    tofile=f"b/{target_str}",
                    lineterm="",
                )
            )
            target.write_text(text_content, encoding="utf-8")
            return ActionExecutionResult(
                "modify" if target_existed else "create",
                target_str,
                True,
                diff=diff,
                output=f"Wrote {len(text_content.encode('utf-8'))} bytes to {target_str}",
            )
        except Exception as exc:
            logger.warning("File action denied/failed for %s: %s", target_str, exc)
            return ActionExecutionResult("write", target_str, False, error=str(exc))

    async def _execute_delete(
        self,
        workspace: Path,
        target_str: str,
    ) -> ActionExecutionResult:
        if not target_str:
            return ActionExecutionResult("delete", "", False, error="No target specified.")
        try:
            target = self._resolve_target(workspace, target_str)
            if not await self._request_file_approval("delete", target_str):
                raise ActionExecutionError("File deletion was not approved by the operator.")
            if target.exists():
                if target.is_dir():
                    raise ActionExecutionError(
                        "Directory deletion is not supported by agent actions."
                    )
                target.unlink()
            return ActionExecutionResult("delete", target_str, True, output=f"Deleted {target_str}")
        except Exception as exc:
            logger.warning("Delete action denied/failed for %s: %s", target_str, exc)
            return ActionExecutionResult("delete", target_str, False, error=str(exc))

    async def _request_file_approval(self, operation: str, target: str) -> bool:
        """Require explicit operator approval before changing workspace files."""
        if self.file_approval_handler is None:
            return False
        try:
            approved = self.file_approval_handler(operation, target)
            if inspect.isawaitable(approved):
                approved = await approved
        except Exception as exc:
            logger.warning("File approval failed for %s: %s", target, exc)
            return False
        return approved is True

    async def _execute_command(
        self,
        workspace: Path,
        command_str: str,
        timeout_seconds: float = 60.0,
    ) -> ActionExecutionResult:
        if not command_str:
            return ActionExecutionResult("command", "", False, error="No command specified.")
        if self.terminal_executor is None:
            return ActionExecutionResult(
                "command",
                command_str,
                False,
                error=(
                    "Terminal action blocked: no authorized TerminalExecutor is configured. "
                    "Raw shell execution is disabled."
                ),
            )
        try:
            argv = tuple(shlex.split(command_str, posix=True))
            if not argv:
                raise ActionExecutionError("Command did not contain an executable.")
            request = TerminalRequest(
                argv=argv,
                working_directory=workspace,
                timeout_seconds=timeout_seconds,
                subject="forgex-agent",
            )
            result = await self.terminal_executor.execute(request)
            succeeded = result.status is TerminalExecutionStatus.SUCCESS
            return ActionExecutionResult(
                "command",
                command_str,
                succeeded,
                output=result.stdout,
                error=result.error or (result.stderr if not succeeded else None),
                metadata={
                    "exit_code": result.exit_code,
                    "status": result.status.value,
                    "truncated": result.truncated,
                },
            )
        except Exception as exc:
            logger.warning("Terminal action failed: %s", exc)
            return ActionExecutionResult("command", command_str, False, error=str(exc))

    async def execute_actions(
        self,
        workspace: Path,
        actions: list[dict[str, Any]],
    ) -> dict[str, Any]:
        root = Path(workspace).expanduser().resolve()
        if not root.is_dir():
            raise ActionExecutionError(f"Workspace does not exist: {root}")

        results: list[dict[str, Any]] = []
        files_changed: list[str] = []
        commands_run: list[str] = []
        errors: list[str] = []

        for action in actions:
            if not isinstance(action, dict):
                errors.append("Invalid action: expected a JSON object.")
                continue
            result = await self.execute_action(root, action)
            results.append(result.to_dict())
            if not result.success:
                if result.error:
                    errors.append(f"{result.action_type} on '{result.target}': {result.error}")
                continue
            if result.action_type in {"create", "modify", "delete", "write"} and result.target:
                if result.target not in files_changed:
                    files_changed.append(result.target)
            elif result.action_type == "command" and result.target:
                commands_run.append(result.target)

        return {
            "success": not errors,
            "executed_count": len(results),
            "files_changed": files_changed,
            "commands_run": commands_run,
            "results": results,
            "errors": errors,
        }


__all__ = ["ActionExecutor", "ActionExecutionResult", "ActionExecutionError"]
